  const response = await fetch(buildApiUrl(`/admin/resources/${resourceId}/review`), {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
    credentials: "include"
  });
  return readJsonResponse(response, "Failed to review resource");
