// src/hooks/useResources.js
function useVideos() {
  const { user } = useUser();
  const {
    data: videos,
    error,
    isLoading
  } = useQuery({
    queryKey: ["videos"],
    queryFn: getAllVideos,
    enabled: !!user
    // Only fetch videos if user is logged in
  });
  return { videos, error, isLoading };
}
function useUser() {
  const {
    data: user,
    error,
    isLoading
  } = useQuery({
    queryKey: ["user"],
    queryFn: fetchMe,
    retry: false,
    staleTime: 5 * 60 * 1e3
    // 5 minutes
  });
  return { user, error, isLoading };
}
function useTeacherMaterials() {
  const { user } = useUser();
  const {
    data: materials,
    error,
    isLoading
  } = useQuery({
    queryKey: ["teacher-materials"],
    queryFn: getTeacherMaterials,
    enabled: !!user
  });
  return { materials, error, isLoading };
}
function useAllUsers() {
  const { user } = useUser();
  const { data, error, isLoading } = useQuery({
    queryKey: ["users"],
    queryFn: getAllUser,
    enabled: !!user && user.role === "admin"
  });
  console.log("all users from hook", data);
  console.log("error fetching all users", error);
  return { data, error, isLoading };
}
function useResourceSearch(filters) {
  const { user } = useUser();
  const { data, error, isLoading } = useQuery({
    queryKey: ["resource-search", filters],
    queryFn: () => searchResources(filters),
    enabled: !!user
  });
  return { resources: data || [], error, isLoading };
}
function useLearningDashboard() {
  const { user } = useUser();
  const { data, error, isLoading } = useQuery({
    queryKey: ["learning-dashboard"],
    queryFn: getLearningDashboard,
    enabled: !!user
  });
  return { dashboard: data, error, isLoading };
}
function useBookmarks() {
  const { user } = useUser();
  const { data, error, isLoading } = useQuery({
    queryKey: ["bookmarks"],
    queryFn: getBookmarks,
    enabled: !!user
  });
  return { bookmarks: data || [], error, isLoading };
}
function useManagedResources() {
  const { user } = useUser();
  const { data, error, isLoading } = useQuery({
    queryKey: ["managed-resources"],
    queryFn: getManagedResources,
    enabled: !!user && (user.role === "teacher" || user.role === "librarian")
  });
  return { resources: data || [], error, isLoading };
}
function useOverdueBorrows() {
  const { user } = useUser();
  const { data, error, isLoading } = useQuery({
    queryKey: ["overdue-borrows"],
    queryFn: getOverdueBorrows,
    enabled: !!user && (user.role === "admin" || user.role === "librarian")
  });
  return { overdueBorrows: data || [], error, isLoading };
}

